key=os.urandom(16); nonce=os.urandom(12); pt=os.urandom(61440000); aad=os.urandom(32)
N=len(pt)
def bench(fn, n=20):
    fn()
    t0=time.perf_counter()
    for _ in range(n):
        fn()
    return (time.perf_counter()-t0)/n

def ctr():
    e=Cipher(algorithms.AES(key), modes.CTR(nonce+b'\x00\x00\x00\x02')).encryptor()
    return e.update(pt)+e.finalize()
def gcm():
    e=Cipher(algorithms.AES(key), modes.GCM(nonce)).encryptor()
    e.authenticate_additional_data(aad)
    ct=e.update(pt)+e.finalize()
    tag=e.tag
    return ct,tag
def ecb():
    e=Cipher(algorithms.AES(key), modes.ECB()).encryptor()
    return e.update(pt)+e.finalize()
print('CTR', bench(ctr))
print('GCM', bench(gcm))
print('ECB', bench(ecb))
